// Consistent hashing with virtual nodes
const crypto = require('crypto');

class ConsistentHashRing {
  constructor(virtualNodesPerPhysical = 150) {
    this.vnodes = virtualNodesPerPhysical;
    this.ring = new Map();       // hashPosition -> physicalNodeName
    this.sortedPositions = [];   // all hash positions, sorted
  }

  _hash(key) {
    // Take first 8 hex chars of MD5 and parse as 32-bit int
    return parseInt(
      crypto.createHash('md5').update(key).digest('hex').slice(0, 8),
      16
    );
  }

  addNode(nodeName) {
    for (let i = 0; i < this.vnodes; i++) {
      const pos = this._hash(`${nodeName}#vnode${i}`);
      this.ring.set(pos, nodeName);
      this.sortedPositions.push(pos);
    }
    // Keep positions sorted for binary search
    this.sortedPositions.sort((a, b) => a - b);
    console.log(`Added ${nodeName} with ${this.vnodes} virtual nodes`);
  }

  removeNode(nodeName) {
    for (let i = 0; i < this.vnodes; i++) {
      const pos = this._hash(`${nodeName}#vnode${i}`);
      this.ring.delete(pos);
    }
    this.sortedPositions = this.sortedPositions.filter(p => this.ring.has(p));
    console.log(`Removed ${nodeName}`);
  }

  getNode(key) {
    if (this.sortedPositions.length === 0) throw new Error('Empty ring');
    const h = this._hash(key);
    // Find first ring position >= h (clockwise lookup)
    let lo = 0, hi = this.sortedPositions.length - 1, idx = 0;
    while (lo <= hi) {
      const mid = (lo + hi) >> 1;
      if (this.sortedPositions[mid] >= h) { idx = mid; hi = mid - 1; }
      else lo = mid + 1;
    }
    // If no position >= h, wrap around to position 0
    if (this.sortedPositions[idx] < h) idx = 0;
    return this.ring.get(this.sortedPositions[idx]);
  }

  // Show how many virtual nodes each physical node owns
  distribution() {
    const counts = {};
    for (const name of this.ring.values())
      counts[name] = (counts[name] || 0) + 1;
    return counts;
  }
}

// --- Demonstration ---
const ring = new ConsistentHashRing(150);
['node-a', 'node-b', 'node-c'].forEach(n => ring.addNode(n));

const keys = Array.from({ length: 1000 }, (_, i) => `user:${i}`);
const before = {};
keys.forEach(k => {
  const n = ring.getNode(k);
  before[k] = n;
});

// Add a fourth node
ring.addNode('node-d');

let moved = 0;
keys.forEach(k => {
  if (ring.getNode(k) !== before[k]) moved++;
});
console.log(`Keys moved after adding node: ${moved}/1000 (~${(moved/10).toFixed(1)}%)`);
// Expected: ~250 keys moved (25%), not 750 (75%) as with modulo hashing

console.log('Virtual node distribution:', ring.distribution());
// Each node owns ~150 virtual slots; physical responsibility ~250 keys each

// Demonstrating partition strategy trade-offs

// ── RANGE PARTITIONING with hotspot fix ──────────────────────
function rangePartitionKey(deviceId, timestamp) {
  // Naive: partition by timestamp alone — HOTSPOT
  // All current reads have today's timestamp -> same partition
  const naiveKey = timestamp.toString();

  // Fixed: prefix with bucket derived from deviceId
  const NUM_BUCKETS = 8;
  const bucket = simpleHash(deviceId) % NUM_BUCKETS;
  const spreadKey = `${bucket}:${timestamp}`;

  return { naiveKey, spreadKey };
}

function simpleHash(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++)
    h = (h * 33 ^ str.charCodeAt(i)) >>> 0;
  return h;
}

// Current timestamp — all naive keys would be identical
const now = Date.now();
console.log('Naive key (hotspot):', rangePartitionKey('dev-001', now).naiveKey.slice(0, 8));
console.log('Naive key (hotspot):', rangePartitionKey('dev-002', now).naiveKey.slice(0, 8));
// Both produce same prefix -> same partition -> hotspot!

console.log('Spread key dev-001:', rangePartitionKey('dev-001', now).spreadKey.split(':')[0]);
console.log('Spread key dev-002:', rangePartitionKey('dev-002', now).spreadKey.split(':')[0]);
// Different bucket prefixes -> different partitions

// ── QUORUM CONSISTENCY SIMULATION ────────────────────────────
class QuorumSimulator {
  constructor(N, W, R) {
    this.N = N; this.W = W; this.R = R;
    this.nodes = Array.from({ length: N }, (_, i) => ({ id: i, data: {}, version: 0 }));
  }

  isStronglyConsistent() { return this.W + this.R > this.N; }

  write(key, value, failedNodes = []) {
    const available = this.nodes.filter(n => !failedNodes.includes(n.id));
    if (available.length < this.W)
      throw new Error(`Write failed: only ${available.length} nodes, need W=${this.W}`);
    available.slice(0, this.W).forEach(n => {
      n.data[key] = value;
      n.version++;
    });
    console.log(`Write acknowledged by ${this.W}/${this.N} nodes`);
  }

  read(key, failedNodes = []) {
    const available = this.nodes.filter(n => !failedNodes.includes(n.id));
    if (available.length < this.R)
      throw new Error(`Read failed: only ${available.length} nodes, need R=${this.R}`);
    const responses = available.slice(0, this.R).map(n => n.data[key]);
    // Return highest version (simplified read repair)
    const latest = responses.find(v => v !== undefined) || null;
    console.log(`Read from ${this.R}/${this.N} nodes: [${responses}] -> ${latest}`);
    return latest;
  }
}

// N=3, W=2, R=2 — strong consistency
const q = new QuorumSimulator(3, 2, 2);
console.log('Strongly consistent:', q.isStronglyConsistent()); // true (2+2=4 > 3)
q.write('user:1', 'Alice');
q.read('user:1'); // Always sees 'Alice' — read set overlaps write set

// Write with one node down — still succeeds (W=2, 2 nodes available)
q.write('user:2', 'Bob', [2]); // Node 2 is down
q.read('user:2'); // Reads from nodes 0 and 1 — both have 'Bob'
